import{DetailsProvider}from"./discards.mojom-webui.js";import{SiteDataProvider}from"./site_data.mojom-webui.js";let discardsDetailsProvider;export function getOrCreateDetailsProvider(){if(!discardsDetailsProvider){discardsDetailsProvider=DetailsProvider.getRemote()}return discardsDetailsProvider}let siteDataProvider;export function getOrCreateSiteDataProvider(){if(!siteDataProvider){siteDataProvider=SiteDataProvider.getRemote()}return siteDataProvider}export function maybeMakePlural(s,n){return n===1?s:s+"s"}export function secondsToString(seconds){const SECONDS_PER_MINUTE=60;const MINUTES_PER_HOUR=60;const SECONDS_PER_HOUR=SECONDS_PER_MINUTE*MINUTES_PER_HOUR;const HOURS_PER_DAY=24;const SECONDS_PER_DAY=SECONDS_PER_HOUR*HOURS_PER_DAY;const DAYS_PER_WEEK=7;const SECONDS_PER_WEEK=SECONDS_PER_DAY*DAYS_PER_WEEK;const SECONDS_PER_MONTH=SECONDS_PER_DAY*30.5;const SECONDS_PER_YEAR=SECONDS_PER_DAY*365;if(seconds<SECONDS_PER_MINUTE){return seconds.toString()+maybeMakePlural(" second",seconds)}let minutes=Math.floor(seconds/SECONDS_PER_MINUTE);if(minutes<MINUTES_PER_HOUR){return minutes.toString()+maybeMakePlural(" minute",minutes)}const hours=Math.floor(seconds/SECONDS_PER_HOUR);minutes=minutes%MINUTES_PER_HOUR;if(hours<HOURS_PER_DAY){let s=hours.toString()+maybeMakePlural(" hour",hours);if(minutes>0){s+=" and "+minutes.toString()+maybeMakePlural(" minute",minutes)}return s}const days=Math.floor(seconds/SECONDS_PER_DAY);if(days<DAYS_PER_WEEK){return days.toString()+maybeMakePlural(" day",days)}const weeks=Math.floor(seconds/SECONDS_PER_WEEK);const months=Math.floor(seconds/SECONDS_PER_MONTH);if(months<1){return"over "+weeks.toString()+maybeMakePlural(" week",weeks)}const years=Math.floor(seconds/SECONDS_PER_YEAR);if(years<1){return"over "+months.toString()+maybeMakePlural(" month",months)}return"over "+years.toString()+maybeMakePlural(" year",years)}export function durationToString(secondsAgo){const ret=secondsToString(secondsAgo);if(ret.endsWith(" seconds")||ret.endsWith(" second")){return"just now"}return ret+" ago"}export function boolToString(bool){return bool?"✔":"✘️"}